import React, { useMemo, useState } from "react";
import language from "@/store/language";
import { Button, Card, Modal, Table, TableProps, Input, TableColumnProps, Space, Tooltip } from "@arco-design/web-react";
import { JSONSchemaCustom, SchemaApiJsonPage, SchemaQueryForm, SchemaTable } from "@/components/schema";
import Store from './store';
import { useObserver } from "mobx-react-lite";
import { IconDelete, IconPlus, IconSync } from "@arco-design/web-react/icon";
import { AsyncButton, ProTable, ProTableProps, Selector } from "@/components/custom";

const Index = () => {
    const languageOptions = language.options;
    

    const [store] = useState(() => {
        return new Store();
    })
    

    return useObserver(() => {


        const columns = useMemo(() => {

            return [
                {
                    title: "多语言Key",
                    dataIndex: "languekey",
                    fixed: "left",
                    format: "copy",
                    proCopyValue: (row) => `i18next.t("${row.languekey}")`,
                    width: 180,
                },
                ...languageOptions.map((o) => {
                    const field = o.value.replace('-', '')
                    return {
                        title: o.label,
                        dataIndex: field,
                        width: 180,
                        fixed: o.value == 'zh-CN'? "left" : undefined,
                    } as TableColumnProps;
                }),
                {
                    title: "设置",
                    fixed: "right",
                    width: 80,
                    render: (col, item, index) => {
                        return (
                            <Button
                                status="danger"
                                onClick={() => {
                                    store.deleteLanguage(item)
                                }}
                                icon={
                                    <IconDelete />
                                }
                            ></Button>
                        )
                    }
                }
            ] as ProTableProps['columns']
        },[store.type])
        


        return (
            <div className="h-full p-4 bg-white flex flex-col">
                <div className="flex justify-between items-center mb-4">
                    <div>
                        当前已添加多语言 { store.list.length } 条
                    </div>
                    <Space>
                        <Button type="primary"
                            onClick={() => {
                                store.setVisible(true);
                            }}
                        >添加多语言</Button>
                        <Tooltip content="刷新">
                            <Button
                                onClick={() => {
                                    store.getList();
                                }}
                                icon={<IconSync />}
                            />
                        </Tooltip>
                    </Space>
                </div>
                <div className="grow">
                    <ProTable
                        rowKey={"key"}
                        pagination={false}
                        scroll={{
                            x: true,
                            y: true,
                        }}
                        columns={columns}
                        data={store.list}
                    />
                </div>
                <Modal
                    visible={store.visible}
                    title="添加多语言"
                    onCancel={() => {
                        store.setVisible(false);
                    }}
                    onOk={() => {
                        store.addLanguages();
                    }}
                >
                    <Selector
                        mode="multiple"
                        value={store.values}
                        onChange={store.setValues}
                        filterOption={(item) => {
                            return !store.node[item.value];
                        }}
                        type="langugageAll"
                    />
                </Modal>
            </div>
        )
    })
}


export default Index;