import { observable, action, toJS, computed, makeObservable } from 'mobx';
import ajax from '@/utils/ajax';
import { Message, Modal } from '@arco-design/web-react';
import _ from 'lodash';


class Store {

    @observable type: string = "";
    @observable values = [];
    @observable visible = false;
    @action setVisible = (bool) => {
        this.values = [];
        this.visible = bool;
    }
    @action setValues = (vals) => {
        this.values = vals;
    }
    


    @action setType = (key: string) => {
        this.type = key;
        this.setList([]);
    }

    @observable selectedRowKeys = [];
    @action setSelectedRowKeys = (keys) => {
        this.selectedRowKeys = keys;
    }


    node = {};
    @observable list = [];
    @action setList = (list) => {
        this.list = list;
        this.node = {};
        for (const element of list) {
            this.node[element.languekey] = true;
        }
    }


    // 获取多语言
    getList = () => {
        return ajax.post('/apijson/gets', {
            "LanguageAllRelevance[]": {
                "count": 0,
                "join": "&/LanguageAll",
                "LanguageAllRelevance": {
                    "@column": "id,languekey",
                    "@order": "createdAt-"
                },
                "LanguageAll": {
                    "languekey@": "/LanguageAllRelevance/languekey",
                    "@column": "zhCN,zhTW,zhHK,enUS,deDE,frFR,ruRU,jaJP,koKR"
                }
            }
        }).then((res) => {
            this.setList(res.LanguageAllRelevance)
        })
    }

    constructor(){
        makeObservable(this);
        this.getList();
    }

    deleteLanguage = async (row) => {
        return Modal.confirm({
            title: "提示",
            content: `请确认是否删除【${row.zhCN}】多语言`,
            onOk: () => {
                ajax.post('/apijson/delete', {
                    "LanguageAllRelevance": {
                        id: row.id
                    }
                }).then(() => {
                    Message.success("删除成功");
                    this.getList();
                })
            }
        })
    }

    // 添加多语言
    addLanguages = async () => {
        const list = [...this.values];
        // 去重
        const result = _.differenceBy(list, this.list.map((o) => o.languekey));
        if(result.length){
            await ajax.post('/apijson/post', {
                "LanguageAllRelevance[]": result.map((key) => {
                    return {
                        languekey: key
                    }
                })
            }).then(() => {
                Message.success("新增多语言成功");
                this.getList();
            })
        }else {
            Message.success("无需重复添加")
        }

        this.setVisible(false)
    }

    @action changeValue = (index, key, value) => {
        const result = [...this.list];
        result[index][key] = value;
        this.list = result;
    }


    @action deleteIndex = (index: number) => {
        this.list = this.list.filter((_, i) => i != index);
    }



}


export default Store;